// Style refinement (like GPUI's `refineable` crate): a Style struct, a StyleRefinement with Option
// fields generated by macro, `refine` merging, cascading through hover/active states, and `is_superset_of`.
use std::fmt::Debug;

trait Refineable: Clone {
    type Refinement: Default + Clone + Debug;
    fn refine(&mut self, r: &Self::Refinement);
    fn refined(mut self, r: Self::Refinement) -> Self {
        self.refine(&r);
        self
    }
}

trait RefinementExt: Sized {
    fn merge(&mut self, other: &Self);
    fn merged(mut self, other: Self) -> Self {
        self.merge(&other);
        self
    }
}

macro_rules! refineable {
    (
        #[derive($($d:ident),*)]
        struct $name:ident => $rname:ident {
            $( $field:ident : $ty:ty, )*
        }
    ) => {
        #[derive($($d),*)]
        struct $name { $( $field: $ty, )* }

        #[derive(Default, Clone, Debug, PartialEq)]
        struct $rname { $( $field: Option<$ty>, )* }

        impl Refineable for $name {
            type Refinement = $rname;
            fn refine(&mut self, r: &$rname) {
                $( if let Some(v) = &r.$field { self.$field = v.clone(); } )*
            }
        }

        impl RefinementExt for $rname {
            fn merge(&mut self, o: &Self) {
                $( if o.$field.is_some() { self.$field = o.$field.clone(); } )*
            }
        }

        #[allow(dead_code)]
        impl $rname {
            $(
                fn $field(mut self, v: $ty) -> Self { self.$field = Some(v); self }
            )*
            fn set_count(&self) -> usize {
                0 $( + self.$field.is_some() as usize )*
            }
            fn is_superset_of(&self, o: &Self) -> bool {
                true $( && (o.$field.is_none() || self.$field == o.$field) )*
            }
        }
    };
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct Rgba(u8, u8, u8, u8);

#[derive(Clone, Copy, Debug, PartialEq)]
enum Display {
    Block,
    Flex,
    None,
}

refineable! {
    #[derive(Clone, Debug, PartialEq)]
    struct Style => StyleRefinement {
        display: Display,
        width: f32,
        height: f32,
        padding: [f32; 4],
        background: Rgba,
        text_color: Rgba,
        font_family: String,
        opacity: f32,
    }
}

impl Default for Style {
    fn default() -> Self {
        Style {
            display: Display::Block,
            width: 0.0,
            height: 0.0,
            padding: [0.0; 4],
            background: Rgba(0, 0, 0, 0),
            text_color: Rgba(0, 0, 0, 255),
            font_family: "Sans".into(),
            opacity: 1.0,
        }
    }
}

struct Interactive {
    base: StyleRefinement,
    hover: Option<StyleRefinement>,
    active: Option<StyleRefinement>,
    disabled: Option<StyleRefinement>,
}

#[derive(Clone, Copy)]
struct State {
    hovered: bool,
    pressed: bool,
    disabled: bool,
}

impl Interactive {
    fn compute(&self, s: State) -> Style {
        let mut r = self.base.clone();
        if s.hovered {
            if let Some(h) = &self.hover {
                r.merge(h);
            }
        }
        if s.pressed {
            if let Some(a) = &self.active {
                r.merge(a);
            }
        }
        if s.disabled {
            if let Some(d) = &self.disabled {
                r.merge(d);
            }
        }
        Style::default().refined(r)
    }
}

fn main() {
    let base = StyleRefinement::default()
        .display(Display::Flex)
        .width(120.0)
        .height(32.0)
        .padding([4.0, 8.0, 4.0, 8.0])
        .background(Rgba(30, 30, 30, 255))
        .text_color(Rgba(220, 220, 220, 255));
    println!("base sets {} fields", base.set_count());
    let button = Interactive {
        base: base.clone(),
        hover: Some(StyleRefinement::default().background(Rgba(50, 50, 60, 255))),
        active: Some(StyleRefinement::default().background(Rgba(10, 10, 80, 255)).padding([5.0, 8.0, 3.0, 8.0])),
        disabled: Some(StyleRefinement::default().opacity(0.5).text_color(Rgba(128, 128, 128, 255))),
    };
    let states = [
        ("idle", State { hovered: false, pressed: false, disabled: false }),
        ("hover", State { hovered: true, pressed: false, disabled: false }),
        ("press", State { hovered: true, pressed: true, disabled: false }),
        ("disabled+hover", State { hovered: true, pressed: false, disabled: true }),
    ];
    let idle = button.compute(states[0].1);
    for (name, st) in states {
        let s = button.compute(st);
        println!("{:<15} bg={:?} pad={:?} text={:?} opacity={} same_as_idle={}", name, s.background, s.padding, s.text_color, s.opacity, s == idle);
    }
    println!("{:#?}", idle);

    let a = StyleRefinement::default().width(10.0).font_family("Mono".into());
    let b = StyleRefinement::default().width(20.0).height(5.0);
    let ab = a.clone().merged(b.clone());
    let ba = b.clone().merged(a.clone());
    println!("ab = {:?}", ab);
    println!("ba width={:?} height={:?} font={:?}", ba.width, ba.height, ba.font_family);
    println!("ab ⊇ b: {} ab ⊇ a: {} ba ⊇ a: {}", ab.is_superset_of(&b), ab.is_superset_of(&a), ba.is_superset_of(&a));
    let hidden = Style::default().refined(StyleRefinement::default().display(Display::None));
    println!("{:?} {}", hidden.display, hidden.font_family);
}
